"use strict";(globalThis.webpackChunkweb||=[]).push([[8454],{8454(e){e.exports=JSON.parse('{"group":"callRoutines","count":107,"entries":{"PRXCHANGE":{"help":"Performs a pattern-matching replacement."},"PRXDEBUG":{"help":"Enables Perl regular expressions in a DATA step to send debug output to the SAS log."},"PRXFREE":{"help":"Frees unneeded memory that was allocated for a Perl regular expression."},"PRXNEXT":{"help":"Returns the position and length of a substring that matches a pattern and iterates \\nover multiple matches within one string."},"PRXPOSN":{"help":"Returns the start position and length for a capture buffer."},"PRXSUBSTR":{"help":"Returns the position and length of a substring that matches a pattern."},"RXCHANGE":{"help":"Changes one or more substrings that match a pattern."},"RXFREE":{"help":"Frees memory allocated by other regular expression (RX) functions and routines."},"RXSUBSTR":{"help":"Finds the position, length, and score of a substring that matches a pattern."},"CATS":{"help":"Concatenates character strings and removes leading and trailing blanks."},"CATT":{"help":"Concatenates character strings and removes trailing blanks."},"CATX":{"help":"Concatenates character strings, removes leading and trailing blanks, and inserts separators."},"COMPCOST":{"help":"Sets the costs of operations for later use by the COMPGED function."},"MISSING":{"help":"Assigns a missing value to the specified character or numeric variables.."},"SCAN":{"help":"Returns the position and length of a given word from a character expression."},"SCANQ":{"help":"Returns the position and length of a given word from a character expression, and \\nignores delimiters that are enclosed in quotation marks."},"MODULE":{"help":"Calls the external routine without any return code. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the CALL MODULE routine does not execute. \\n\\nSyntax: CALL MODULE(<control-string,> module-name <, argument-1, ..., argument-n>);\\n\\nRequired Argument:\\nmodule-name - is the name of the external module to use.\\n\\nOptional Arguments:\\ncontrol-string\\n  is an optional control string whose first character must be an asterisk (*), followed by any \\n  combination of the following characters:\\n    I\\n    prints the hexadecimal representations of all arguments to the CALL MODULE routine. You can use \\n    this option to help diagnose problems that are caused by incorrect arguments or attribute tables. \\n    If you specify the I option, the E option is implied.\\n    E\\n    prints detailed error messages. Without the E option (or the I option, which supersedes it), \\n    the only error message that the CALL MODULE routine generates is \\"Invalid argument to function,\\" \\n    which is usually not enough information to determine the cause of the error. The E option is \\n    useful for a production environment, whereas the I option is preferable for a development or \\n    debugging environment.\\n    H\\n    provides brief information about the syntax of the CALL MODULE routine, the attribute file format, \\n  and suggested SAS formats and informats. \\n\\nargument - is one or more arguments to pass to the requested routine."},"EXECUTE":{"help":"Resolves an argument and issues the resolved value for execution ."},"SYMPUT":{"help":"Assigns DATA step information to a macro variable."},"SYMPUTX":{"help":"Assigns a value to a macro variable and removes both leading and trailing blanks."},"ALLPERM":{"help":"Generates all permutations of the values of several variables ."},"LOGISTIC":{"help":"Returns the logistic value."},"SOFTMAX":{"help":"Returns the softmax value."},"STDIZE":{"help":"Standardizes the values of one or more variables."},"TANH":{"help":"Returns the hyperbolic tangent."},"RANBIN":{"help":"Returns a random variate from a binomial distribution."},"RANCAU":{"help":"Returns a random variate from a Cauchy distribution."},"RANEXP":{"help":"Returns a random variate from an exponential distribution."},"RANGAM":{"help":"Returns a random variate from a gamma distribution."},"RANNOR":{"help":"Returns a random variate from a normal distribution."},"RANPERK":{"help":"Randomly permutes the values of the arguments, and returns a permutation of \\nk out of n values."},"RANPERM":{"help":"Randomly permutes the values of the arguments."},"RANPOI":{"help":"Returns a random variate from a Poisson distribution."},"RANTBL":{"help":"Returns a random variate from a tabled probability distribution ."},"RANTRI":{"help":"Returns a random variate from a triangular distribution."},"RANUNI":{"help":"Returns a random variate from a uniform distribution."},"STREAMINIT":{"help":"Specifies a seed value to use for subsequent random number generation by the RAND function ."},"POKE":{"help":"Writes a value directly into memory on a 32-bit platform . \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the CALL POKE routine does not execute. \\n\\nSyntax: CALL POKE(source, pointer <, length> <, floating-point>);\\n\\nRequired Arguments:\\nsource\\n  specifies a constant, variable, or expression that contains a value to write into memory \\npointer\\n  specifies a numeric expression that contains the virtual address of the data that the CALL POKE routine alters.\\n\\nOptional Arguments:\\nlength\\n  specifies a numeric constant, variable, or expression that contains the number of bytes to write from the source \\n  to the address that is indicated by pointer. If you omit length, the action that the CALL POKE routine takes depends \\n  on whether source is a character value or a numeric value:\\n    •If source is a character value, the CALL POKE routine copies the entire value of source to the specified memory location.\\n    •If source is a numeric value, the CALL POKE routine converts source to a long integer and writes into memory the number \\n      of bytes that constitute a pointer.\\n\\n  z/OS Specifics\\n  Under z/OS, pointers are 3 or 4 bytes long, depending on the situation. \\n\\nfloating-point\\n  specifies that the value of source is stored as a floating-point number. The value of floating-point can be any number."},"POKELONG":{"help":"Writes a value directly into memory on 32-bit and 64-bit platforms. \\n    \\nInteraction:\\nWhen a SAS server is in a locked-down state, the CALL POKELONG routine does not execute. \\n\\nSyntax: CALL POKELONG(source, pointer <, length> <, floating-point>);\\nRequired Arguments:\\nsource\\n  specifies a character constant, variable, or expression that contains a value to write into memory. \\npointer\\n  specifies a character string that contains the virtual address of the data that the CALL POKELONG routine alters.\\n\\nOptional Arguments:\\nlength\\n  specifies a numeric SAS expression that contains the number of bytes to write from the source to the address \\n  that is indicated by the pointer. If you omit length, the CALL POKELONG routine copies the entire value of \\n  source to the specified memory location. \\nfloating-point\\n  specifies that the value of source is stored as a floating-point number. The value of floating-point can be any number."},"SLEEP":{"help":"Suspends the execution of a program that invokes this call routine for a specified \\nperiod of time."},"SYSTEM":{"help":"Submits an operating environment command for execution."},"LABEL":{"help":"Assigns a variable label to a specified character variable."},"SET":{"help":"Links SAS data set variables to DATA step or macro variables that have the same \\nname and data type."},"VNAME":{"help":"Assigns a variable name as the value of a specified variable."},"VNEXT":{"help":"Returns the name, type, and length of a variable that is used in a DATA step."},"ALLCOMB":{"help":"Generates all combinations of the values of n variables taken k at a time in a \\nminimal change order."},"ALLCOMBI":{"help":"Generates all combinations of the indices of n objects taken k at a time in a \\nminimal change order."},"GRAYCODE":{"help":"Generates all subsets of n items in a minimal change order."},"IS8601_CONVERT":{"help":"Converts an ISO 8601 interval to datetime and duration values, or converts datetime \\nand duration values to an ISO 8601 interval. \\n\\nSyntax: CALL IS8601_CONVERT(convert-from, convert-to, <from-variables>, <to-variables>,<date-time-replacements>);"},"LEXCOMB":{"help":"Generates all distinct combinations of the non-missing values of n variables taken \\nk at a time in lexicographic order."},"LEXCOMBI":{"help":"Generates all combinations of the indices of n objects taken k at a time in \\nlexicographic order."},"LEXPERK":{"help":"Generates all distinct permutations of the non-missing values of n variables taken \\nk at a time in lexicographic order."},"LEXPERM":{"help":"Generates all distinct permutations of the non-missing values of several variables \\nin lexicographic order."},"SORTC":{"help":"Sorts the values of character arguments."},"SORTN":{"help":"Sorts the values of numeric arguments."},"DQSCHEMEAPPLY":{"help":"Applies a scheme and returns a transformed value and a transformation flag."},"DQPARSE":{"help":"Returns a parsed character value and a status flag."},"DEFINE":{"help":"Sets the value of an attribute for a particular column in the current row."},"INSERT_CATALOG":{"help":"Inserts a SAS catalog into a package. \\n    \\nSyntax: \\nCALL INSERT_CATALOG(packageId, libname, memname, desc, nameValue, rc); "},"INSERT_DATASET":{"help":"Inserts a SAS data set into a package. \\n    \\nSyntax:\\nCALL INSERT_DATASET(packageId, libname, memname, desc, nameValue, rc <, properties, propValue1, ...propValueN>); "},"INSERT_FDB":{"help":"Inserts a financial database into a package. \\n    \\nSyntax: \\nCALL INSERT_FDB(packageId, libname, memname, desc, nameValue, rc);"},"INSERT_FILE":{"help":"Inserts a file into a package. \\n    \\nSyntax \\nCALL INSERT_FILE(packageId, filename, filetype, mimeType, desc, nameValue, rc<, properties, propValue1, ...propValueN>);"},"INSERT_HTML":{"help":"Inserts HTML files into a package. \\n    \\nSyntax:\\nCALL INSERT_HTML(packageId, body, bodyUrl, frame, frameUrl, contents, contentsUrl, page, pageUrl, desc, nameValue, rc<, properties, propValue1, ...propValueN>);"},"INSERT_MDDB":{"help":"Inserts a SAS multidimensional database into a package. \\n    \\nSyntax:\\nCALL INSERT_MDDB(packageId, libname, memname, desc, nameValue, rc);"},"INSERT_PACKAGE":{"help":"Inserts a package into another package."},"INSERT_REF":{"help":"Inserts a reference into a package. \\n    \\nSyntax:  \\nCALL INSERT_REF(packageId, referenceType, reference, desc, nameValue, rc);"},"INSERT_SQLVIEW":{"help":"Inserts a PROC SQL view into a package. \\n    \\nSyntax \\nCALL INSERT_SQLVIEW(packageId, libname, memname, desc, nameValue, rc);"},"INSERT_VIEWER":{"help":"Inserts a viewer into a package. \\n    \\nSyntax: \\nCALL INSERT_VIEWER(packageId, filename, mimeType, desc, nameValue, rc<, properties, propValue1, ...propValueN>);"},"PACKAGE_BEGIN":{"help":"Initializes a package and returns a unique package identifier. \\n    \\nSyntax: \\nCALL PACKAGE_BEGIN(packageId, desc, nameValue, rc<, properties, propValue1, ...propValueN>);"},"PACKAGE_END":{"help":"Frees the resources that are associated with a package. \\n   \\nSyntax \\nCALL PACKAGE_END(packageId, rc);"},"PACKAGE_PUBLISH":{"help":"Publishes the specified package. The method of publication depends on the type of delivery transport."},"COMPANION_NEXT":{"help":"Retrieves the next companion HTML file in the ODS HTML set. \\n    \\nSyntax \\nCALL COMPANION_NEXT(entryId, path, filename, url, rc <, properties, propValue1, ...propValueN>);"},"ENTRY_FIRST":{"help":"Returns header information for the first entry in a package. \\n    \\nSyntax: \\nCALL ENTRY_FIRST(packageId, entryId, entryType, userSpecString, desc, nameValue, rc<, properties, propValue1, ...propValueN>);"},"ENTRY_NEXT":{"help":"Returns header information from the next entry in a package. \\n    \\nSyntax: \\nCALL ENTRY_NEXT(packageId, entryId, entryType, userSpecString, desc, nameValue, rc<, properties, propValue1, ...propValueN>);"},"PACKAGE_DESTROY":{"help":"Deletes a package. \\n    \\nSyntax \\nCALL PACKAGE_DESTROY(packageId, rc);"},"PACKAGE_FIRST":{"help":"Returns the header information for the first package in the package list. \\n    \\nSyntax \\nCALL PACKAGE_FIRST(pkgListId, packageId, numEntries, desc, dateTime, nameValue, channel, rc<, properties, propValue1, ...propValueN>);"},"PACKAGE_NEXT":{"help":"Returns the header information for the next package in the package list. \\n    \\nSyntax:\\nCALL PACKAGE_NEXT(pkgListId, packageId, numEntries, desc, dateTime, nameValue, channel, rc<, properties, propValue1, ...propValueN>);"},"PACKAGE_TERM":{"help":"Frees all resources associated with the package list identifier. \\n    \\nSyntax \\nCALL PACKAGE_TERM(pkgListId, rc);"},"RETRIEVE_CATALOG":{"help":"Retrieves a catalog from a package. \\n    \\nSyntax \\nCALL RETRIEVE_CATALOG(entryId, libname, memname, rc);"},"RETRIEVE_DATASET":{"help":"This CALL routine retrieves a data set entry from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_DATASET(entryId, libname, memname, rc<, properties, propValue1, ...propValueN>);"},"RETRIEVE_FDB":{"help":"Retrieves a financial database entry from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_FDB(entryId, libname, memname, rc); "},"RETRIEVE_FILE":{"help":"Retrieves an external binary or text file from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_FILE(entryId, filename, rc);"},"RETRIEVE_HTML":{"help":"Retrieves an HTML entry from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_HTML(entryId, path, body, bodyUrl, frame, frameUrl, contents, contentsUrl, pages, pagesUrl, rc<, properties, propValue1, ...propValueN>);"},"RETRIEVE_MDDB":{"help":"Retrieves an MDDB entry from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_MDDB(entryId, libname, memname, rc);"},"RETRIEVE_NESTED":{"help":"Retrieves the descriptive header information for a nested package entry.\\n    \\nSyntax: \\nCALL RETRIEVE_NESTED(entryId,packageId, numEntries, desc, dateTime, nameValue, rc);"},"RETRIEVE_PACKAGE":{"help":"This CALL routine retrieves descriptive header information for all packages. \\n    \\nSyntax \\nCALL RETRIEVE_PACKAGE(pkgListId, retrievalType, retrievalInfo, totalPackages, rc<, properties, propValue1, propValueN>);"},"RETRIEVE_REF":{"help":"Retrieves a reference from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_REF(entryId, referenceType, reference, rc);"},"RETRIEVE_SQLVIEW":{"help":"Retrieves a PROC SQL view from a package. \\n    \\nSyntax: \\nCALL RETRIEVE_SQLVIEW(entryId, libname, memname, rc);"},"RETRIEVE_VIEWER":{"help":"Retrieves a viewer entry from a package.\\n\\nSyntax:\\nCALL RETRIEVE_VIEWER(entryId, filename, rc<, properties, propValue1, ...propValueN>);"},"RANCOMB":{"help":"Permutes the values of the arguments, and returns a random combination of \\nk out of n values.\\n\\nSyntax: \\nCALL RANCOMB(seed, k, variable-1<, variable–2, ...> ); \\n\\nRequired Arguments:\\nseed \\n  is a numeric variable that contains the random number seed. \\nk \\n  is the number of values that you want to have in the random combination. \\n  variable specifies all numeric variables, or all character variables that have the same length. \\n  K values of these variables are randomly permuted."},"ADDMATRIX":{"help":"Performs an elementwise addition of two matrices or a matrix and a scalar.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL ADDMATRIX(X, Y, Z); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x n (that is, X[m, n]) or a scalar. \\nY \\n  specifies an input matrix with dimensions m x n (that is, Y[m, n]) or a scalar. \\nZ \\n  specifies an output matrix with dimensions m x n (that is, Z[m, n]), such that Z= X + Y"},"CHOL":{"help":"Calculates the Cholesky decomposition for a given symmetric matrix.\\n    \\nSyntax: [Valid for PROC FCMP  only!]\\nCALL CHOL(X, Y <, validate>); \\n\\nRequired Arguments:\\nX \\n  specifies a symmetric positive-definite input matrix with dimensions m x m (that is, X[m, m]). \\nY \\n  specifies an output matrix with dimensions m x m (that is, Y[m, m]). This variable contains \\n  the Cholesky decomposition, such that \\n  \\n      Z = YY*\\n\\n  where Y is a lower triangular matrix with strictly positive diagonal entries and Y* denotes the \\n  conjugate transpose of Y. \\n  Note: If X is not symmetric positive-definite, then Y will be filled with missing values. \\n\\nOptional Argument:\\nvalidate \\n  specifies an optional argument that can increase the processing speed by avoiding error checking. \\n  The argument can take the following values: \\n  \\n    0 the matrix X will be checked for symmetry. This is the default if the validate argument is omitted.  \\n    1 the matrix is assumed to be symmetric."},"DET":{"help":"Calculates the determinant of a specified matrix that should be square.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL DET(X, a); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x n (that is, X[m, m]). \\na \\n  specifies the returned determinate value, such that \\n  \\n    a = |X|"},"DYNAMIC_ARRAY":{"help":"Enables an array that is declared within a function to change size in an efficient manner.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL DYNAMIC_ARRAY(array–name, new-dim1–size, ...,, new-dimN-size); \\n\\nRequired Arguments:\\narray-name \\n  specifies the name of a temporary array. \\nnew-dim-size \\n  specifies a new size for the temporary array."},"ELEMMULT":{"help":"Performs an elementwise multiplication of two matrices.\\n\\nSyntax:\\nCALL ELEMMULT(X, Y, Z); \\n\\nRequired Arguments \\nX \\n  specifies an input matrix with dimensions m x n (that is, X[m, n]). \\nY \\n  specifies an input matrix with dimensions m x n (that is, Y[m, n]). \\nZ \\n  specifies an output matrix with dimensions m x n (that is, Z[m, n])."},"EXPMATRIX":{"help":"Returns a matrix e**tA given the input matrix A and a multiplier t. \\n    \\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL EXPMATRIX(X, t, Y); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x m (that is, X[m, m]). \\nt \\n  specifies a double scalar value. \\nY \\n  specifies an output matrix with dimensions m x m (that is, Y[m, m]), such that \\n\\n      Y = Ԑ**tẊ where Ẋ is the mean of X"},"FILLMATRIX":{"help":"Replaces all of the element values of the input matrix with the specified value.\\n \\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL FILLMATRIX(X, Y); \\n\\nRequired Arguments:\\nX \\n  specifies an input numeric matrix. \\nY \\n  specifies the numeric value that will fill the matrix."},"IDENTITY":{"help":"Converts the input matrix to an identity matrix.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL IDENTITY(X); \\n\\nRequired Argument:\\nX \\n  specifies an input matrix with dimensions m x m (that is, X[m, m])."},"INV":{"help":"Calculates a matrix that is the inverse of the provided input matrix that should \\nbe a square, non-singular matrix.\\n \\n[Valid for PROC FCMP  only!] \\n\\nSyntax:\\nCALL INV(X, Y); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x m (that is, X[m, m]). \\nY \\n  specifies an output matrix with dimensions m x m (that is, Y[m, m]), such that \\n  \\n    Y[m.m] = X\'[m,m]\\n\\n  where \' denotes inverse \\n  \\n    X x Y = Y x X = I\\n  \\nand I is the identity matrix."},"INVERSE":{"help":"Calculates a matrix that is the inverse of the provided input matrix that should \\nbe a square, non-singular matrix.\\n \\n[Valid for PROC FCMP  only!] \\n\\nSyntax:\\nCALL INV(X, Y); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x m (that is, X[m, m]). \\nY \\n  specifies an output matrix with dimensions m x m (that is, Y[m, m]), such that \\n  \\n    Y[m.m] = X\'[m,m]\\n\\n  where \' denotes inverse \\n  \\n    X x Y = Y x X = I\\n  \\nand I is the identity matrix."},"MULT":{"help":"Calculates the multiplicative product of two input matrices.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL MULT(X, Y, Z); \\n\\nRequired Arguments \\nX \\n  specifies an input matrix with dimensions m x n (that is, X[m, n]). \\nY \\n  specifies an input matrix with dimensions n x p (that is, Y[n, p]). \\nZ \\n  specifies an output matrix with dimensions m x p (that is, Z[m, p]), such that \\n\\n    Z[m,p] = X[m,n] x Y[n,p]"},"POWER":{"help":"Raises a square matrix to a given scalar value.\\n \\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL POWER(X, a, Y); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x m (that is, X[m, m]). \\na \\n  specifies an integer scalar value (power). \\nY \\n  specifies an output matrix with dimensions m x m (that is, Y[m, m]), such that \\n\\n    Y = X**a"},"SETNULL":{"help":"Sets a pointer element of a structure to null.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL SETNULL(pointer-element); \\n\\nRequired Argument:\\npointer-element \\n  is a pointer to a structure."},"STRUCTINDEX":{"help":"Enables you to access each structure element in an array of structures.\\n    \\nSyntax:\\nCALL STRUCTINDEX(struct_array, index, struct_element); \\n\\nRequired Arguments:\\nstruct_array \\n  specifies an array.\\nindex \\n  is a 1–based index as used in most SAS arrays. \\nstruct_element \\n  points to an element in the array."},"SUBTRACTMATRIX":{"help":"Performs an element-wide subtraction of two matrices or a matrix and a scalar.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL SUBTRACTMATRIX(X, Y, Z); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x n (that is, X[m, n]) or a scalar. \\nY \\n  specifies an input matrix with dimensions m x n (that is, Y[m, n]) or a scalar. \\nZ \\n  specifies an output matrix with dimensions m x n (that is, Z[m, n]), such that \\n    \\n      Z = X - Y"},"TRANSPOSE":{"help":"Returns the transpose of a matrix.\\n\\n[Valid for PROC FCMP  only!]\\n\\nSyntax: \\nCALL TRANSPOSE(X, Y); \\n\\nRequired Arguments:\\nX \\n  specifies an input matrix with dimensions m x n (that is, X[m, n]). \\nY \\n  specifies an output matrix with dimensions n x m (that is, Y[n, m])"},"ZEROMATRIX":{"help":"Replaces all of the element values of the numeric input matrix with 0.\\n    \\n[Valid for PROC FCMP  only!]\\n\\nSyntax:\\nCALL ZEROMATRIX(X); \\n\\nRequired Argument \\nX \\n  specifies a numeric input matrix."}}}')}}]);